 old_base text := 'https://aiometadata.elfhosted.com/stremio/23e5c3c4-cc2f-40a8-8608-8fd2f51fc5cb';
begin
 for owner_id in select user_id from public.ember_sync_heads union select user_id from public.ember_sync_records loop
  insert into public.ember_sync_heads(user_id) values(owner_id) on conflict do nothing;
  perform 1 from public.ember_sync_heads where user_id=owner_id for update;
  update public.ember_sync_heads set revision=greatest(revision,coalesce((select max(r.revision) from public.ember_sync_records r where r.user_id=owner_id),0)) where user_id=owner_id;
  for scope_prefix in
   select 'account:' where exists(select 1 from public.ember_sync_records where user_id=owner_id and left(id,16)='account:profile:' and not deleted)
   union select 'space:'||coalesce(data->>'id',substr(id,17))||':' from public.ember_sync_records where user_id=owner_id and left(id,16)='account:profile:' and not deleted and data->>'isolatedAddons'='true'
   union select '' where not exists(select 1 from public.ember_sync_records where user_id=owner_id and left(id,16)='account:profile:' and not deleted)
  loop
   for addon in select value from jsonb_array_elements(presets) loop
    record_id:=scope_prefix||'addon:'||(addon->>'base');
    select data into prior from public.ember_sync_records where user_id=owner_id and not deleted and left(id,length(scope_prefix||'addon:'))=scope_prefix||'addon:'
      and data->'manifest'->>'id'=addon->'manifest'->>'id'
      and (data->>'base'=addon->>'base' or data->>'base'=old_base and addon->'manifest'->>'id'='aio-metadata')
      order by (id=record_id) desc limit 1;
    if prior ? 'enabled' then addon:=jsonb_set(addon,'{enabled}',prior->'enabled');end if;
    if not exists(select 1 from public.ember_sync_records where user_id=owner_id and id=record_id and not deleted and data=addon) then
     update public.ember_sync_heads set revision=revision+1 where user_id=owner_id returning revision into next_revision;
     insert into public.ember_sync_records(user_id,id,data,deleted,revision,mutation) values(owner_id,record_id,addon,false,next_revision,gen_random_uuid()::text)
      on conflict(user_id,id) do update set data=excluded.data,deleted=false,revision=excluded.revision,mutation=excluded.mutation;
    end if;
   end loop;
   record_id:=scope_prefix||'addon:'||old_base;
   if exists(select 1 from public.ember_sync_records where user_id=owner_id and id=record_id and not deleted) then
    update public.ember_sync_heads set revision=revision+1 where user_id=owner_id returning revision into next_revision;
    update public.ember_sync_records set data=null,deleted=true,revision=next_revision,mutation=gen_random_uuid()::text where user_id=owner_id and id=record_id;
   end if;
  end loop;
 end loop;
end;$ember_catalog_0710$;
